ALTER TABLE "platform"."wecom_receipts" ADD COLUMN "media_rejection_reason" text;--> statement-breakpoint
ALTER TABLE "platform"."wecom_receipts" ADD COLUMN "media_rejection_max_bytes" bigint;--> statement-breakpoint
ALTER TABLE "platform"."wecom_receipts" ADD CONSTRAINT "wecom_media_rejection" CHECK (("platform"."wecom_receipts"."acceptance_status" = 'media_rejected') = ("platform"."wecom_receipts"."media_rejection_reason" is not null) and ("platform"."wecom_receipts"."media_rejection_reason" is null or "platform"."wecom_receipts"."media_rejection_reason" in ('unsupported_channel','unsupported_type','too_large','expired','failed')) and ("platform"."wecom_receipts"."media_rejection_reason" is not distinct from 'too_large') = ("platform"."wecom_receipts"."media_rejection_max_bytes" is not null) and ("platform"."wecom_receipts"."media_rejection_max_bytes" is null or "platform"."wecom_receipts"."media_rejection_max_bytes" between 1 and 9007199254740991));--> statement-breakpoint
ALTER TABLE "platform"."wecom_receipts" ADD CONSTRAINT "wecom_acceptance_status" CHECK ("platform"."wecom_receipts"."acceptance_status" in ('accepted','busy','unavailable','new_conversation','media_rejected'));